import React, { forwardRef } from "react";
import { clsx } from "clsx";

import { useMenu } from "../hooks/use-menu";
import { MenuClasses } from "../menu.styles";

const MenuGroup = forwardRef<HTMLDivElement, React.ComponentPropsWithoutRef<"div">>(
  ({ children, className, ...props }, ref) => {
    const { RadixComponent } = useMenu();
    return (
      <RadixComponent.Group ref={ref} className={clsx(MenuClasses.group, className)} {...props}>
        {children}
      </RadixComponent.Group>
    );
  },
);
MenuGroup.displayName = "Menu.Group";

export { MenuGroup };
